function cleanText(value) {
  if (!value) return "";

  return String(value)
    .normalize("NFKC")
    .replace(/<[^>]*>/g, " ")
    .replace(/[\u0000-\u001F\u007F]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function sheetSafe(value) {
  const text = cleanText(value);

  if (/^[=+\-@]/.test(text)) {
    return "'" + text;
  }

  return text;
}

function normalizeEmail(value) {
  return cleanText(value).toLowerCase();
}

function normalizeWebsite(value) {
  let website = cleanText(value);

  if (!website) return "";

  if (!/^https?:\/\//i.test(website)) {
    website = "https://" + website;
  }

  try {
    return new URL(website).toString();
  } catch {
    return "";
  }
}


// -------------------------
// Sanitize input
// -------------------------

const firstName = cleanText(inputData.first_name);
const lastName = cleanText(inputData.last_name);
const email = normalizeEmail(inputData.email);
const company = cleanText(inputData.company);
const jobTitle = cleanText(inputData.job_title);
const phone = cleanText(inputData.phone);
const website = normalizeWebsite(inputData.website);

const city = cleanText(inputData.city);
const region = cleanText(inputData.region);
const country = cleanText(inputData.country);

const message = cleanText(inputData.message);


// -------------------------
// Normalize inquiry type
// -------------------------

const inquiryTypes = {
  "request a demo": "Request a Demo",
  "pricing": "Pricing",
  "product information": "Product Information",
  "partnership": "Partnership",
  "support": "Support",
  "other": "Other"
};

const rawInquiryType = cleanText(inputData.inquiry_type);

const inquiryType =
  inquiryTypes[rawInquiryType.toLowerCase()] || "";


// -------------------------
// Validation
// -------------------------

const errors = [];
const warnings = [];

if (!firstName) errors.push("First name is missing");
if (!lastName) errors.push("Last name is missing");

if (!email) {
  errors.push("Email is missing");
} else {
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  if (!emailPattern.test(email)) {
    errors.push("Email format is invalid");
  }
}

if (!company) {
  errors.push("Company is missing");
}

if (!inquiryType) {
  errors.push("Inquiry type is missing or invalid");
}

if (!city) {
  errors.push("City is missing");
}

if (!region) {
  errors.push("State / Province is missing");
}

if (!country) {
  errors.push("Country / Region is missing");
}

if (!message) {
  errors.push("Message is missing");
} else if (message.length < 10) {
  errors.push("Message is too short");
}

if (inputData.website && !website) {
  warnings.push("Website format could not be validated");
}


// -------------------------
// Run metadata
// -------------------------

const now = new Date();

const runId =
  "VS-" +
  now.toISOString().replace(/[-:.TZ]/g, "").slice(0, 14) +
  "-" +
  Math.random().toString(36).substring(2, 7).toUpperCase();

const validationStatus =
  errors.length === 0 ? "Valid" : "Invalid";


// -------------------------
// Output
// -------------------------

return {
  run_id: runId,
  processing_started_at: now.toISOString(),

  validation_status: validationStatus,
  validation_errors: errors.join("; "),
  validation_warnings: warnings.join("; "),

  first_name: firstName,
  last_name: lastName,
  email: email,
  company: company,
  job_title: jobTitle,
  phone: phone,
  website: website,

  inquiry_type: inquiryType,

  city: city,
  region: region,
  country: country,

  original_message: message,

  log_first_name: sheetSafe(firstName),
  log_last_name: sheetSafe(lastName),
  log_email: sheetSafe(email),
  log_company: sheetSafe(company),
  log_city: sheetSafe(city),
  log_region: sheetSafe(region),
  log_country: sheetSafe(country),
  log_original_message: sheetSafe(message)
};

function normalize(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\([^)]*\)/g, "")  // Removes abbreviations in parentheses
    .replace(/\./g, "")
    .replace(/\s+/g, " ")
    .trim();
}

const city = String(inputData.city || "").trim();
const region = normalize(inputData.region);
const country = normalize(inputData.country);

// -----------------------------------
// CANADA
// -----------------------------------

const canadaEastern = [
  "ontario", "on",
  "quebec", "qc",
  "new brunswick", "nb",
  "nova scotia", "ns",
  "prince edward island", "pei", "pe",
  "newfoundland and labrador", "nl",
  "newfoundland", "labrador"
];

const canadaCentral = [
  "manitoba", "mb",
  "saskatchewan", "sk"
];

const canadaWest = [
  "alberta", "ab",
  "british columbia", "bc"
];

// -----------------------------------
// UNITED STATES — EASTERN
// -----------------------------------

const usEastern = [
  "connecticut", "ct",
  "delaware", "de",
  "florida", "fl",
  "georgia", "ga",
  "maine", "me",
  "maryland", "md",
  "massachusetts", "ma",
  "new hampshire", "nh",
  "new jersey", "nj",
  "new york", "ny",
  "north carolina", "nc",
  "pennsylvania", "pa",
  "rhode island", "ri",
  "south carolina", "sc",
  "vermont", "vt",
  "virginia", "va",
  "west virginia", "wv",
  "district of columbia", "dc"
];

// -----------------------------------
// UNITED STATES — CENTRAL
// -----------------------------------

const usCentral = [
  "alabama", "al",
  "arkansas", "ar",
  "illinois", "il",
  "indiana", "in",
  "iowa", "ia",
  "kansas", "ks",
  "kentucky", "ky",
  "louisiana", "la",
  "michigan", "mi",
  "minnesota", "mn",
  "mississippi", "ms",
  "missouri", "mo",
  "nebraska", "ne",
  "north dakota", "nd",
  "ohio", "oh",
  "oklahoma", "ok",
  "south dakota", "sd",
  "tennessee", "tn",
  "texas", "tx",
  "wisconsin", "wi"
];

// -----------------------------------
// UNITED STATES — WEST
// -----------------------------------

const usWest = [
  "alaska", "ak",
  "arizona", "az",
  "california", "ca",
  "colorado", "co",
  "hawaii", "hi",
  "idaho", "id",
  "montana", "mt",
  "nevada", "nv",
  "new mexico", "nm",
  "oregon", "or",
  "utah", "ut",
  "washington", "wa",
  "wyoming", "wy"
];

// -----------------------------------
// ROUTING
// -----------------------------------

let salesRegion = "Unassigned";
let accountOwner = "Unassigned";
let routingStatus = "Needs Review";

const isCanada =
  country === "canada" ||
  country === "ca";

const isUSA =
  country === "united states" ||
  country === "united states of america" ||
  country === "usa" ||
  country === "us";

if (isCanada) {

  if (canadaEastern.includes(region)) {
    salesRegion = "Eastern";
    accountOwner = "Nina Patel";
    routingStatus = "Assigned";

  } else if (canadaCentral.includes(region)) {
    salesRegion = "Central";
    accountOwner = "Jordan Lee";
    routingStatus = "Assigned";

  } else if (canadaWest.includes(region)) {
    salesRegion = "West";
    accountOwner = "Avery Morgan";
    routingStatus = "Assigned";
  }

} else if (isUSA) {

  if (usEastern.includes(region)) {
    salesRegion = "Eastern";
    accountOwner = "Nina Patel";
    routingStatus = "Assigned";

  } else if (usCentral.includes(region)) {
    salesRegion = "Central";
    accountOwner = "Jordan Lee";
    routingStatus = "Assigned";

  } else if (usWest.includes(region)) {
    salesRegion = "West";
    accountOwner = "Avery Morgan";
    routingStatus = "Assigned";
  }
}

return {
  city: city,
  region: inputData.region,
  country: inputData.country,
  sales_region: salesRegion,
  account_owner: accountOwner,
  routing_status: routingStatus
};

